// === ESTRUCTURA DEL PATRÓN PROXY ===

// 1. Interfaz (Servicio)
interface Image {
  display(): void;
  getInfo(): string;
}

// 2. Objeto Real (costoso de crear)
class HighResImage implements Image {
  private loaded = false;

  constructor(private filename: string) {
    console.log(`⏳ Cargando imagen de alta resolución: ${filename}...`);
    // Simular carga lenta (3 segundos)
    this.simulateLoading();
    this.loaded = true;
    console.log(`✅ Imagen cargada: ${filename}`);
  }

  private simulateLoading() {
    // En producción: descarga de disco/red, decodifica, etc.
  }

  display() {
    console.log(`🖼️ Mostrando ${this.filename} en alta resolución`);
  }

  getInfo() {
    return `${this.filename} (${this.loaded ? 'cargada' : 'no cargada'})`;
  }
}

// 3. Proxy (controla el acceso)
class ImageProxy implements Image {
  private realImage: HighResImage | null = null;

  constructor(private filename: string) {}

  display() {
    if (!this.realImage) {
      // Lazy loading: crear solo cuando se necesita
      this.realImage = new HighResImage(this.filename);
    }
    this.realImage.display();
  }

  getInfo() {
    return this.realImage ? this.realImage.getInfo() : `${this.filename} (proxy - no cargada)`;
  }
}

// Uso:
const gallery: Image[] = [
  new ImageProxy('foto1.jpg'),
  new ImageProxy('foto2.jpg'),
  new ImageProxy('foto3.jpg'),
];

// Solo se carga foto1.jpg cuando se muestra
console.log('Galería creada — 0 imágenes cargadas');
gallery[0].display(); // Solo esta carga la imagen real
gallery[1].display(); // Esta también carga
// foto3.jpg nunca se carga si el usuario no la ve

