// Carga TODAS las imágenes al iniciar — lento y wasteful
class Gallery {
  private images: HighResImage[] = [];

  constructor(filenames: string[]) {
    // Carga todas las imágenes de una vez
    for (const file of filenames) {
      this.images.push(new HighResImage(file)); // 3s cada una
    }
  }

  displayAll() {
    this.images.forEach(img => img.display());
  }
}

// 10 imágenes × 3s = 30s de carga inicial
const gallery = new Gallery(['foto1.jpg', 'foto2.jpg', ... 'foto10.jpg']);

